// Generated by vibes-espmatter – HTTP server core: routes, pages, JSON helpers.
#include "espm_web.h"
#include "espm_config.h"

#include <esp_log.h>
#include <cstdlib>
#include <cstring>
#include <cinttypes>

static const char *TAG = "mesp_web";

struct route_t {
    const char *uri;
    httpd_method_t method;
    esp_err_t (*handler)(httpd_req_t *req);
};

struct page_t {
    std::string uri;
    const char *start;
    const char *end;
    std::string manifest_uri;
    const char *manifest;
};

static std::vector<route_t> s_routes;
static std::vector<page_t> s_pages;
static httpd_handle_t s_server = nullptr;

void mesp_web_add(const char *uri, httpd_method_t method, esp_err_t (*handler)(httpd_req_t *req))
{
    s_routes.push_back({uri, method, handler});
}

void mesp_web_add_page(const char *uri, const char *start, const char *end, const char *manifest)
{
    std::string base = strcmp(uri, "/") == 0 ? "" : uri;
    s_pages.push_back({uri, start, end, base + "/manifest.webmanifest", manifest});
}

void mesp_web_add_cors(httpd_req_t *req)
{
    httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");
    httpd_resp_set_hdr(req, "Access-Control-Allow-Headers", "Authorization, Content-Type");
    httpd_resp_set_hdr(req, "Access-Control-Allow-Methods", "GET, POST, OPTIONS");
}

bool mesp_web_read_body(httpd_req_t *req, std::string &out, size_t max_len)
{
    if (req->content_len > max_len) {
        mesp_web_send_error(req, "413 Payload Too Large", "body too large");
        return false;
    }
    out.resize(req->content_len);
    size_t received = 0;
    while (received < req->content_len) {
        int r = httpd_req_recv(req, &out[received], req->content_len - received);
        if (r == HTTPD_SOCK_ERR_TIMEOUT) {
            continue;
        }
        if (r <= 0) {
            mesp_web_send_error(req, "400 Bad Request", "failed to read body");
            return false;
        }
        received += r;
    }
    return true;
}

static int hex_value(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

bool mesp_parse_u64(const std::string &s, uint64_t &out)
{
    if (s.empty()) return false;
    char *end = nullptr;
    out = strtoull(s.c_str(), &end, 0);
    return end && *end == '\0';
}

bool mesp_web_param(const std::string &body, const char *key, std::string &out)
{
    size_t key_len = strlen(key);
    size_t pos = 0;
    while (pos <= body.size()) {
        size_t end = body.find('&', pos);
        if (end == std::string::npos) end = body.size();
        if (end - pos > key_len && body.compare(pos, key_len, key) == 0 && body[pos + key_len] == '=') {
            out.clear();
            for (size_t i = pos + key_len + 1; i < end; i++) {
                char c = body[i];
                if (c == '+') {
                    out += ' ';
                } else if (c == '%' && i + 2 < end && hex_value(body[i + 1]) >= 0 && hex_value(body[i + 2]) >= 0) {
                    out += (char)(hex_value(body[i + 1]) * 16 + hex_value(body[i + 2]));
                    i += 2;
                } else {
                    out += c;
                }
            }
            return true;
        }
        pos = end + 1;
    }
    return false;
}

esp_err_t mesp_web_send_json(httpd_req_t *req, const std::string &json)
{
    mesp_web_add_cors(req);
    httpd_resp_set_type(req, "application/json");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    return httpd_resp_send(req, json.c_str(), json.size());
}

esp_err_t mesp_web_send_error(httpd_req_t *req, const char *status, const char *message)
{
    Json j;
    j.obj().key("error").str(message).end_obj();
    httpd_resp_set_status(req, status);
    return mesp_web_send_json(req, j.out());
}

/** Pages are public: they show their own login and fetch everything else from the API. */
static esp_err_t page_handler(httpd_req_t *req)
{
    const page_t *page = (const page_t *)req->user_ctx;
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_set_hdr(req, "Content-Encoding", "gzip");
    // A page only changes with a firmware update.
    httpd_resp_set_hdr(req, "Cache-Control", "no-cache");
    return httpd_resp_send(req, page->start, page->end - page->start);
}

/** `/` without a page there: to the first page, if there is one. */
static esp_err_t no_page_handler(httpd_req_t *req)
{
    if (!s_pages.empty()) {
        httpd_resp_set_status(req, "302 Found");
        httpd_resp_set_hdr(req, "Location", s_pages.front().uri.c_str());
        return httpd_resp_send(req, nullptr, 0);
    }
    httpd_resp_set_type(req, "text/plain; charset=utf-8");
    return httpd_resp_sendstr(req, MESP_DEVICE_NAME " – no web interface, API at /api/");
}

// ---------------------------------------------------------------------------------------------
// Home screen app: the web app manifests of the pages (public, like the pages)
// ---------------------------------------------------------------------------------------------

/** They only change with a firmware update; a day of caching is plenty. */
static esp_err_t send_static(httpd_req_t *req, const char *type, const void *data, size_t len)
{
    httpd_resp_set_type(req, type);
    httpd_resp_set_hdr(req, "Cache-Control", "max-age=86400");
    return httpd_resp_send(req, (const char *)data, len);
}

static esp_err_t manifest_handler(httpd_req_t *req)
{
    const char *manifest = ((const page_t *)req->user_ctx)->manifest;
    return send_static(req, "application/manifest+json", manifest, strlen(manifest));
}

static esp_err_t options_handler(httpd_req_t *req)
{
    mesp_web_add_cors(req);
    httpd_resp_set_status(req, "204 No Content");
    return httpd_resp_send(req, nullptr, 0);
}

bool mesp_web_require(httpd_req_t *req, mesp_role_t role, mesp_session_t *out)
{
    mesp_session_t s = mesp_web_session(req);
    if (out) *out = s;
    if (s.role == MESP_ROLE_NONE) {
        mesp_web_send_error(req, "401 Unauthorized", "please log in");
    } else if (s.must_change) {
        mesp_web_send_error(req, "403 Forbidden", "please change your password first");
    } else if (s.role < role) {
        mesp_web_send_error(req, "403 Forbidden", "admins only");
    } else {
        return true;
    }
    return false;
}

bool mesp_web_authorized(httpd_req_t *req)
{
    return mesp_web_require(req, MESP_ROLE_ADMIN);
}

esp_err_t mesp_web_start()
{
    httpd_config_t config = HTTPD_DEFAULT_CONFIG();
    config.server_port = MESP_WEB_PORT;
    config.max_uri_handlers = s_routes.size() + 3 * s_pages.size() + 8;
    config.stack_size = 8192;
    config.lru_purge_enable = true;
    config.uri_match_fn = httpd_uri_match_wildcard;

    esp_err_t err = httpd_start(&s_server, &config);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Failed to start web server: %s", esp_err_to_name(err));
        return err;
    }

    bool has_root = false;
    for (const page_t &page : s_pages) {
        void *ctx = (void *)&page;
        httpd_uri_t uri = {.uri = page.uri.c_str(), .method = HTTP_GET, .handler = page_handler, .user_ctx = ctx};
        httpd_register_uri_handler(s_server, &uri);
        if (page.uri == "/") {
            has_root = true;
        } else {
            std::string slash = page.uri + "/";
            uri.uri = slash.c_str(); // copied by the server
            httpd_register_uri_handler(s_server, &uri);
        }
        if (page.manifest) {
            httpd_uri_t manifest = {.uri = page.manifest_uri.c_str(), .method = HTTP_GET, .handler = manifest_handler, .user_ctx = ctx};
            httpd_register_uri_handler(s_server, &manifest);
        }
    }
    if (!has_root) {
        httpd_uri_t root = {.uri = "/", .method = HTTP_GET, .handler = no_page_handler, .user_ctx = nullptr};
        httpd_register_uri_handler(s_server, &root);
    }
    for (const route_t &route : s_routes) {
        httpd_uri_t uri = {.uri = route.uri, .method = route.method, .handler = route.handler, .user_ctx = nullptr};
        httpd_register_uri_handler(s_server, &uri);
    }
    httpd_uri_t options = {.uri = "/api/*", .method = HTTP_OPTIONS, .handler = options_handler, .user_ctx = nullptr};
    httpd_register_uri_handler(s_server, &options);

    ESP_LOGI(TAG, "HTTP server listening on port %d (%u routes)", MESP_WEB_PORT, (unsigned)s_routes.size());
    return ESP_OK;
}

// ---------------------------------------------------------------------------------------------
// Json
// ---------------------------------------------------------------------------------------------

void Json::sep()
{
    if (m_after_key) {
        m_after_key = false;
        return;
    }
    if (!m_first.empty()) {
        if (!m_first.back()) m_out += ',';
        m_first.back() = false;
    }
}

Json &Json::obj()
{
    sep();
    m_out += '{';
    m_first.push_back(true);
    return *this;
}

Json &Json::end_obj()
{
    m_out += '}';
    m_first.pop_back();
    return *this;
}

Json &Json::arr()
{
    sep();
    m_out += '[';
    m_first.push_back(true);
    return *this;
}

Json &Json::end_arr()
{
    m_out += ']';
    m_first.pop_back();
    return *this;
}

Json &Json::key(const char *k)
{
    sep();
    escape(k);
    m_out += ':';
    m_after_key = true;
    return *this;
}

Json &Json::str(const char *v)
{
    sep();
    escape(v);
    return *this;
}

void Json::escape(const char *v)
{
    m_out += '"';
    for (const char *p = v ? v : ""; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
        case '"': m_out += "\\\""; break;
        case '\\': m_out += "\\\\"; break;
        case '\n': m_out += "\\n"; break;
        case '\r': m_out += "\\r"; break;
        case '\t': m_out += "\\t"; break;
        default:
            if (c < 0x20) {
                char buf[8];
                snprintf(buf, sizeof(buf), "\\u%04x", c);
                m_out += buf;
            } else {
                m_out += (char)c;
            }
        }
    }
    m_out += '"';
}

Json &Json::num(long long v)
{
    sep();
    m_out += std::to_string(v);
    return *this;
}

Json &Json::unum(unsigned long long v)
{
    sep();
    m_out += std::to_string(v);
    return *this;
}

Json &Json::dbl(double v)
{
    sep();
    char buf[32];
    snprintf(buf, sizeof(buf), "%.3f", v);
    m_out += buf;
    return *this;
}

Json &Json::boolean(bool v)
{
    sep();
    m_out += v ? "true" : "false";
    return *this;
}

Json &Json::null()
{
    sep();
    m_out += "null";
    return *this;
}

Json &Json::hex(const uint8_t *data, size_t len)
{
    sep();
    m_out += '"';
    static const char digits[] = "0123456789abcdef";
    for (size_t i = 0; i < len; i++) {
        m_out += digits[data[i] >> 4];
        m_out += digits[data[i] & 0xf];
    }
    m_out += '"';
    return *this;
}
